pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress through the stream
    let progress = step_index as f64 / total_items as f64;

    // Ratios describing the current bin state
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let post_residual_f64 = post_residual as f64;
    let next_ratio = if bin_capacity > 0 {
        next_item_size as f64 / bin_capacity as f64
    } else {
        0.0
    };

    // Primary term: post residual weighted by the remaining progress.
    // Late in the stream we penalise large residuals more heavily.
    let term1 = post_residual_f64 * (1.0 + (1.0 - progress).powi(2));

    // Penalty for many open bins that still have a lot of free space.
    let term2 = (open_bins_count as f64) * (1.0 - residual_ratio);

    // Bonus for bins that are scarce relative to the number of open bins.
    // Fewer fitting bins -> lower score.
    let term3 = ((fitting_bins_count as f64) / (open_bins_count as f64 + 1.0)).powi(2);

    // Anticipate the next item: if it is large we prefer bins that leave more room.
    let term4 = next_ratio * (1.0 - (post_residual_f64 / bin_capacity as f64));

    // Combine terms: lower score is better.
    // We add the penalties, subtract the scarcity bonus, and add the anticipation penalty.
    let score = term1 + term2 + term4 - term3;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    // Reward using the sole fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize small dead‑space gaps
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Penalize if the next item cannot fit in the leftover space
    if next_item_size > 0 && next_item_size > post_residual {
        score += 25.0;
    }

    // Pressure from many open bins
    score += (open_bins_count as f64) * 2.0;

    // New‑bin special handling
    if bin_residual == bin_capacity {
        if post_residual > 50 {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // Late‑stage packing: avoid large residuals
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 && post_residual > 10 {
        score += 10.0;
    }

    // Penalize residual larger than the current mean
    if (post_residual as f64) > mean_residual {
        score += 0.1 * ((post_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic score starts with the residual space left in the bin after placement
    let mut score = post_residual as f64;

    // Progress factor: early in the stream we penalize waste more heavily
    let progress = step_index as f64 / total_items as f64;
    let inv_progress = 1.0 - progress;

    // 1. Dead‑space penalty: if the remaining gap cannot fit the next item,
    //    add a large penalty scaled by how early we are.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 1000.0 * inv_progress;
    } else {
        // 2. Small‑gap penalty: gaps smaller than 10 units are unlikely to be useful
        if post_residual < 10 {
            let small_gap = 10 - post_residual;
            score += small_gap as f64 * 5.0 * inv_progress;
        }
    }

    // 3. New‑bin pressure: discourage opening a new bin when many are already open
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 10.0 * inv_progress;
    }

    // 4. Unique‑fit bonus: if this bin is the only one that can fit the item,
    //    reward it heavily (especially early in the stream).
    if fitting_bins_count == 1 {
        score -= 50.0 * inv_progress;
    }

    // 5. Mean residual adjustment: if the average free space is high,
    //    prefer tighter packing (penalize using open bins).
    if bin_capacity > 0 {
        score -= (mean_residual / bin_capacity as f64) * 20.0 * inv_progress;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start from the post-placement residual as baseline
    let mut score = post_residual as f64;

    // Sole fitting bin: strongly reward it
    if fitting_bins_count == 1 {
        score -= 1_000.0;
    }

    // Prefer placing larger items (they reduce future waste)
    score -= (item_size as f64) * 0.5;

    // Lookahead penalty: if the next item won't fit after this placement
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Time‑horizon adjustment: early steps favor tighter packing,
    // late steps penalize large residuals to reduce fragmentation.
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.3 {
        score -= (bin_residual as f64) * 0.1;
    } else if progress > 0.7 {
        score += (bin_residual as f64) * 0.1;
    }

    // If many bins are open, we prefer to use existing ones.
    if open_bins_count > 10 {
        score -= (open_bins_count as f64) * 0.2;
    }

    // Prefer bins whose residual is close to the current mean residual.
    score -= (mean_residual - post_residual as f64).abs() * 0.3;

    // Special handling for a brand‑new empty bin candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 5 || mean_residual > 30.0 {
            // Favor opening a new bin when many bins exist or residuals are high.
            score -= 500.0;
        } else {
            // Otherwise, slightly penalize opening a new bin.
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised stream progress
    let t = step_index as f64 / total_items as f64;

    // Core polynomial coupling of post‑residual with stream progress
    let base = post_residual as f64 * (1.0 - t).powi(3);

    // Penalise using many open bins
    let open_penalty = (open_bins_count as f64).powi(2) * 0.01;

    // Penalise deviation from the mean residual
    let mean_penalty = (post_residual as f64 - mean_residual).abs() * 0.05;

    // Penalise bins that would leave too little space for the next item
    let next_penalty =
        ((next_item_size as f64 - post_residual as f64).max(0.0)).powi(2) * 0.02;

    // Reward bins when few options are available
    let fit_reward = -1.0 / (fitting_bins_count as f64).max(1.0);

    base + open_penalty + mean_penalty + next_penalty + fit_reward
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placing the item
    let mut score = post_residual as f64;

    // Strict dead‑space avoidance: if the residual can't fit the next item,
    // impose a huge penalty to prevent this bin from being chosen.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 1_000.0; // large penalty for dead space
    }

    // Open‑bin pressure: prefer to close bins.  Subtract a constant per
    // currently open bin so that the heuristic tends to reuse bins rather
    // than create new ones unless necessary.
    score -= (open_bins_count as f64) * 0.5;

    // Encourage bins whose residual is close to the current mean residual.
    // If this bin's residual is larger than the average, reduce the score
    // slightly to favor tighter packing.
    if post_residual as f64 > mean_residual {
        score -= 0.2 * (post_residual as f64 - mean_residual);
    }

    // Optional: mild step‑based adjustment (later in the stream we become
    // slightly stricter).  This keeps the heuristic dynamic across the
    // sequence but does not dominate the other terms.
    let progress = step_index as f64 / total_items as f64;
    score -= 0.1 * progress;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start with the post‑residual as the baseline
    let mut score = post_residual as f64;

    // Prefer a fit that is close to the average residual
    let mean_diff = mean_residual - post_residual as f64;
    score -= 0.5 * mean_diff * mean_diff;

    // Lookahead: reward bins that can still fit the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let diff = post_residual as f64 - next_item_size as f64;
            let ratio = if post_residual > 0 {
                diff / post_residual as f64
            } else {
                0.0
            };
            score -= 10.0 * ratio;
        } else {
            // Penalize if the bin will be unable to hold the next item
            score += 5.0;
        }
    }

    // If this is the only bin that can fit the current item, prioritize it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Otherwise, slightly penalize many fitting bins to favor tighter packing
        score += (fitting_bins_count as f64) * 2.0;
    }

    // Penalize having many open bins (fragmentation)
    score += (open_bins_count as f64) * 0.5;

    // Time horizon: near the end of the stream we prefer reusing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= 5.0 * progress;
    } else {
        score += progress;
    }

    // Special handling for a brand‑new empty bin
    if bin_residual == bin_capacity {
        // Encourage opening a new bin only when necessary
        score += 30.0;
        if fitting_bins_count == 0 {
            // If no existing bin can fit, make the new bin attractive
            score -= 30.0;
        }
    }

    // Clamp to non‑negative values
    if score < 0.0 {
        score = 0.0;
    }
    score
}
